DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS customers;

CREATE TABLE customers (
    customer_id  BIGINT,
    first_name   VARCHAR,
    last_name    VARCHAR,
    email        VARCHAR,
    city         VARCHAR,
    state        VARCHAR,
    signup_date  VARCHAR,
    phone        VARCHAR,
    total_spent  VARCHAR
);

CREATE TABLE products (
    product_id    BIGINT,
    product_name  VARCHAR,
    category      VARCHAR,
    price         DECIMAL(10,2),
    in_stock      BIGINT
);

CREATE TABLE orders (
    order_id      BIGINT,
    customer_id   BIGINT,
    order_date    DATE,
    status        VARCHAR,
    total_amount  DECIMAL(10,2)
);

CREATE TABLE order_items (
    order_item_id BIGINT,
    order_id      BIGINT,
    product_id    BIGINT,
    quantity      BIGINT,
    unit_price    DECIMAL(10,2)
);

